{
 "stages": [
  {
   "name": "mine",
   "command": [
    "python",
    "-m",
    "vectorsearch.data.mine_negatives"
   ],
   "timeout": 36000.0,
   "check": true,
   "expect": {
    "files": [
     "vectorsearch/experiments/unified-baseline_e5-small-en-ru/negatives.parquet"
    ],
    "assert": "hard negatives mined for at least 90% of the training queries and saved to negatives.parquet"
   }
  },
  {
   "name": "train",
   "command": [
    "python",
    "-m",
    "vectorsearch.train",
    "--train.base_model=/home/jovyan/data/embedder/d0rj/e5-small-en-ru",
    "--train.loss.type=nll_cos",
    "--train.loss.temperature=0.05",
    "--train.loss.thr=0.1",
    "--train.loss.uniformity_weight=0.0",
    "--train.loss.use_batch_centering=false",
    "--train.loss.rdrop_alpha=0.5",
    "--train.training.n_epochs=15",
    "--train.training.batch_size=8192",
    "--train.training.gradient_accumulation_steps=2",
    "--train.training.learning_rate=0.001",
    "--train.training.warmup_ratio=0.2",
    "--train.training.weight_decay=0.1",
    "--train.negatives.n_negatives=2"
   ],
   "timeout": 36000.0,
   "check": true,
   "expect": {
    "files": [
     "vectorsearch/experiments/unified-baseline_e5-small-en-ru/final/model.safetensors"
    ],
    "assert": "all 15 epochs completed and final model saved under final/model.safetensors"
   },
   "needs": [
    "vectorsearch/experiments/unified-baseline_e5-small-en-ru/negatives.parquet"
   ]
  }
 ]
}

